#!/usr/bin/env bash
# Trade-chain test suite: escrow (state machine + split payout, Flutterwave mocked)
# and logistics (job lifecycle, app-less rider link, USSD menu logic). No migration.
# Run afterwards:  python manage.py test escrow logistics --keepdb
set -uo pipefail

BR="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo '')"
if [ -n "$BR" ] && [ "$BR" != "dev" ]; then
  echo ">> Refusing: current branch is '$BR', not 'dev'."; exit 1
fi
if [ ! -f manage.py ]; then echo ">> Run from the Django project root (where manage.py is)."; exit 1; fi
if [ ! -d escrow ] || [ ! -d logistics ]; then echo ">> escrow/ or logistics/ app dir not found."; exit 1; fi

write_if_absent () {
  if [ -f "$1" ]; then
    echo "   - exists, left as-is: $1"
  else
    printf '%s' "$2" | base64 --decode > "$1" && echo "   OK created $1"
  fi
}

write_if_absent escrow/test_trade_chain.py ""
write_if_absent logistics/test_logistics_chain.py ""

echo ""
echo ">> Done. Run the suite:"
echo "     python manage.py test escrow logistics --keepdb"
echo ">> Rollback: rm -f escrow/test_trade_chain.py logistics/test_logistics_chain.py"
